INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('8MVVUXcWjxg', 2, 'UC3iSLVH0MxHfwO69oHKpvog', '2019-08-27', NULL, 'PENDING_REVIEW', '얼라이브 맥스 데일리', 'Alive', '["MULTIVITAMIN"]', 'NOT_RECOMMEND', FALSE, '["GENERAL"]', '[{"category": "OTHER", "text": "성분 섞임으로 인한 반응 불확실"}]', '성분 종류가 매우 많아 데코레이션식으로 여러 원료를 섞어 넣은 점을 문제 삼으며, 성분들이 섞였을 때 일어날 반응이 불분명해 개인적으로 피하라고 설명.', X'', 'text-embedding-3-small', 639, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('8MVVUXcWjxg', 3, 'UC3iSLVH0MxHfwO69oHKpvog', '2019-08-27', NULL, 'PENDING_REVIEW', '라이프익스텐션 투퍼데이', 'Life Extension', '["MULTIVITAMIN"]', 'RECOMMEND', FALSE, '["GENERAL"]', '[{"category": "OTHER", "text": "비타민 D 형태가 아쉬움"}]', '가격 대비 성분 균형이 좋아 가성비가 뛰어나며 셀레늄·활성형 B군 등 포인트가 좋아 추천 제품 중 하나로 꼽음. 다만 비타민 D 형태가 아쉬운 점을 지적.', X'', 'text-embedding-3-small', 778, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('8MVVUXcWjxg', 4, 'UC3iSLVH0MxHfwO69oHKpvog', '2019-08-27', (SELECT catalog_product_id FROM catalog_products WHERE data_source = 'DSLD' AND external_id = '263865'), 'RESOLVED', '솔가 VM-2000', 'Solgar', '["MULTIVITAMIN"]', 'RECOMMEND', FALSE, '["GENERAL"]', '[{"category": "PREGNANCY_LACTATION", "text": "임산부는 비타민A 주의"}]', 'B군 고함량(특히 B군을 100 수준으로 맞춘 점)과 알비온 킬레이트 미네랄 사용 등으로 B군 섭취를 중시하는 사람에게 장점이 있어 특정 목적(고용량 B군)으로 추천한다고 설명.', X'', 'text-embedding-3-small', 996, NULL, 'review-extract-v3');
