INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('9JBaSCxRgAg', 1, 'UCMFk5S7g5DY-CZNVh_Kyz_A', '2022-06-24', NULL, 'PENDING_REVIEW', '고려은단 멀티비타민 올인원', NULL, '["MULTIVITAMIN", "CALCIUM", "MAGNESIUM"]', 'NEUTRAL', FALSE, '["GENERAL", "BONE"]', '[{"category": "PILL_SIZE", "text": "알이 너무 크다"}, {"category": "OTHER", "text": "불필요한 요오드가 들어있다"}]', '가격이 저렴하고 칼슘·마그네슘을 많이 넣은 가성비 제품으로 개별포장 되어 있어 변질에 강한 점을 장점으로 설명, 대신 알 크기와 요오드 포함을 단점으로 지적함.', X'', 'text-embedding-3-small', 363, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('Jov3l-F7vQw', 0, 'UC3iSLVH0MxHfwO69oHKpvog', '2020-03-28', (SELECT catalog_product_id FROM catalog_products WHERE data_source = 'DSLD' AND external_id = '269265'), 'RESOLVED', '닥터스 베스트 프랑스 레드와인 추출물', 'DOCTOR''S BEST', '["OTHER"]', 'RECOMMEND', FALSE, '["GENERAL", "CHOLESTEROL"]', '[]', '적포도주(프랑스 레드와인) 추출물로 레스베라트롤과 기타 폴리페놀이 포함된 제품으로, 원재료와 함량을 보고 선택하라고 설명하며 선택지로 추천함.', X'', 'text-embedding-3-small', 381, NULL, 'review-extract-v3');
