INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('fdJQueq479s', 0, 'UCMFk5S7g5DY-CZNVh_Kyz_A', '2022-09-03', (SELECT catalog_product_id FROM catalog_products WHERE data_source = 'DSLD' AND external_id = '336343'), 'RESOLVED', '쏜 글루타민', 'Thorne', '["OTHER"]', 'RECOMMEND', FALSE, '["GUT"]', '[]', '식도염과 장 염증 회복을 위해 점막 재생 목적으로 꾸준히 복용했고 체감 호전이 있었다고 설명함.', X'', 'text-embedding-3-small', 274, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('flGQRzNw0AA', 0, 'UC3iSLVH0MxHfwO69oHKpvog', '2020-01-02', NULL, 'PENDING_REVIEW', '오로라 리포좀 글루타치온', NULL, '["OTHER"]', 'RECOMMEND', FALSE, '["LIVER", "SKIN_HAIR", "GENERAL"]', '[]', '리포좀 형태 중 가성비 최고로 소개됨. 가격 대비 글루타치온 함량이 높아 흡수 효율과 비용 효율을 중점으로 추천함.', X'', 'text-embedding-3-small', 689, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('flGQRzNw0AA', 1, 'UC3iSLVH0MxHfwO69oHKpvog', '2020-01-02', NULL, 'PENDING_REVIEW', '클리커 글루타치온', NULL, '["OTHER"]', 'NEUTRAL', FALSE, '["LIVER", "SKIN_HAIR"]', '[]', '입안에서 녹여 흡수하는 설하정 형태로 혈중 생체이용률이 더 높다는 연구 결과를 설명하며 장단점을 소개함.', X'', 'text-embedding-3-small', 720, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('flGQRzNw0AA', 2, 'UC3iSLVH0MxHfwO69oHKpvog', '2020-01-02', NULL, 'PENDING_REVIEW', '쏜사 SR형 글루타치온', 'Thorne', '["OTHER"]', 'NOT_RECOMMEND', FALSE, '["GENERAL", "LIVER"]', '[]', '쏜(Thorne)사의 SR 타입은 서서히 흡수되어 지속성이 있다는 설명을 하되, 가격 대비 효율성이 낮아 개인적으로는 추천하지 않는다는 취지로 평가함.', X'', 'text-embedding-3-small', 824, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('kDXMPUDQK4I', 0, 'UCMFk5S7g5DY-CZNVh_Kyz_A', '2020-02-13', (SELECT catalog_product_id FROM catalog_products WHERE data_source = 'DSLD' AND external_id = '274705'), 'RESOLVED', '캘리포니아 골드 내추럴 마그네슘(킬레이트)', 'California Gold Nutrition', '["MAGNESIUM"]', 'RECOMMEND', FALSE, '["FATIGUE", "STRESS", "GENERAL"]', '[]', '영상의 5대 기초 조합 중 하나로 소개되며, 기본적인 피로·만성 염증·스트레스 관리를 위한 구성으로 하루에 하나씩 챙겨 먹는다고 설명.', X'', 'text-embedding-3-small', 95, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('kDXMPUDQK4I', 1, 'UCMFk5S7g5DY-CZNVh_Kyz_A', '2020-02-13', NULL, 'PENDING_REVIEW', '나우푸드 슈퍼 안티옥시던트', 'NOW', '["MILK_THISTLE", "CURCUMIN", "OTHER"]', 'RECOMMEND', FALSE, '["GENERAL", "SKIN_HAIR", "BLOOD_CIRCULATION"]', '[]', '다른 항산화제 제품과 섞어 만성 염증·혈관 건강 예방 및 피부 미용 목적의 항산화 조합으로 복용한다고 설명.', X'', 'text-embedding-3-small', 161, NULL, 'review-extract-v3');
