INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('kDXMPUDQK4I', 3, 'UCMFk5S7g5DY-CZNVh_Kyz_A', '2020-02-13', NULL, 'PENDING_REVIEW', '대웅제약 비타민 B군', NULL, '["VITAMIN_B1", "VITAMIN_B6", "VITAMIN_B12", "FOLATE", "NIACIN"]', 'RECOMMEND', FALSE, '["FATIGUE", "STRESS", "GENERAL"]', '[]', '기본 5대 조합 중 하나로 피로와 스트레스 관리를 위해 복용하는 비타민 B군 제품이라고 소개.', X'', 'text-embedding-3-small', 95, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('kePYsBUc7og', 0, 'UCMFk5S7g5DY-CZNVh_Kyz_A', '2021-05-27', NULL, 'PENDING_REVIEW', '국내 정식 유통 미네랄 제품', NULL, '["CALCIUM", "MAGNESIUM", "VITAMIN_D", "VITAMIN_K", "ZINC", "OTHER"]', 'RECOMMEND', FALSE, '["BONE", "GENERAL"]', '[{"category": "OVERDOSE", "text": "비타민 D 과다 가능성 언급"}]', '국내에서 정식 유통되는 복합 미네랄로 칼슘·마그네슘 비율이 적절하고 비타민 D와 트레이스 미네랄이 포함된다는 이유로 뼈 건강과 미네랄 보충 목적에 추천했다.', X'', 'text-embedding-3-small', 133, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('kePYsBUc7og', 1, 'UCMFk5S7g5DY-CZNVh_Kyz_A', '2021-05-27', NULL, 'PENDING_REVIEW', '약국용 복합 미네랄 제품', NULL, '["CALCIUM", "MAGNESIUM", "VITAMIN_D", "VITAMIN_K", "ZINC", "OTHER"]', 'RECOMMEND', FALSE, '["BONE", "GENERAL"]', '[{"category": "PILL_SIZE", "text": "정제 크기와 섭취 알 수가 많음"}]', '약국 전용 제품으로 칼슘·마그네슘이 균형있게 들어가고 비타민 D와 병아리콩 추출물 등 부원료가 포함되어 있어 종합 미네랄 보충으로 추천했다. 다만 알 수가 많고 정제가 큰 점을 단점으로 언급했다.', X'', 'text-embedding-3-small', 230, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('kePYsBUc7og', 2, 'UCMFk5S7g5DY-CZNVh_Kyz_A', '2021-05-27', NULL, 'PENDING_REVIEW', '리스토어 with K2 (해외직구 제품)', NULL, '["CALCIUM", "MAGNESIUM", "VITAMIN_D", "VITAMIN_K", "ZINC", "OTHER"]', 'RECOMMEND', FALSE, '["BONE", "GENERAL"]', '[{"category": "OTHER", "text": "일부 미네랄이 빠져 있음"}]', '해외직구 제품으로 가성비가 좋고 비타민 K2가 충분히 들어있어 골격·혈관 관리 목적에 좋다고 평가했다. 다만 일부 미네랄이 빠진 점과 산화마그네슘 사용을 단점으로 언급했다.', X'', 'text-embedding-3-small', 322, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('nRUCyzjPRaI', 0, 'UCMFk5S7g5DY-CZNVh_Kyz_A', '2023-01-20', NULL, 'PENDING_REVIEW', '트루땡 초인계 알티 오메가3', NULL, '["OMEGA3"]', 'RECOMMEND', FALSE, '["GENERAL"]', '[]', '고순도·개별포장·원료사가 공개된 고퀄 제품으로 가성비는 낮지만 품질을 우선하는 사람에게 적합하다고 설명.', X'', 'text-embedding-3-small', 218, NULL, 'review-extract-v3');
