INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('uOhROLXBIK4', 0, 'UC3iSLVH0MxHfwO69oHKpvog', '2024-07-18', NULL, 'PENDING_REVIEW', '얼라이브 (천연 비타민C)', NULL, '["VITAMIN_C"]', 'NEUTRAL', FALSE, '["GENERAL", "IMMUNITY"]', '[]', '천연 아세로라 기반 제품으로 플라보노이드가 함께 들어있어 아이들이나 저용량을 원하는 사람에게 적당하나, 비타민C 고함량 목적(메가도스)에는 가성비가 나쁨.', X'', 'text-embedding-3-small', 2, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('uOhROLXBIK4', 1, 'UC3iSLVH0MxHfwO69oHKpvog', '2024-07-18', NULL, 'PENDING_REVIEW', '레이크 어베뉴 (합성 비타민C, 해외 제품 예시)', NULL, '["VITAMIN_C"]', 'RECOMMEND', FALSE, '["GENERAL", "IMMUNITY"]', '[]', '가성비가 좋고 메가도스를 하려는 사람들에게 무난한 선택이라 설명. 다만 실제로는 국내 제품을 권장한다고 언급.', X'', 'text-embedding-3-small', 95, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('uOhROLXBIK4', 2, 'UC3iSLVH0MxHfwO69oHKpvog', '2024-07-18', NULL, 'PENDING_REVIEW', '솔라레이 (합성 비타민C + 플라보노이드)', 'SOLARAY', '["VITAMIN_C"]', 'NEUTRAL', FALSE, '["GENERAL", "IMMUNITY"]', '[]', '합성 비타민C에 플라보노이드를 혼합한 제품으로 천연과 합성의 중간적 장단점이 있어 가성비와 섭취량 면에서 절충형으로 소개됨.', X'', 'text-embedding-3-small', 157, NULL, 'review-extract-v3');
INSERT INTO review_mentions (video_id, mention_no, channel_id, published_at, catalog_product_id, resolve_status, product_name_ko, brand_en, ingredients, stance, is_sponsored, purpose_tags, cautions, context, embedding, embedding_model, start_sec, evidence_quote, prompt_version) VALUES ('uOhROLXBIK4', 3, 'UC3iSLVH0MxHfwO69oHKpvog', '2024-07-18', NULL, 'PENDING_REVIEW', '나우 (중성 비타민C, 칼슘 또는 마그네슘 염)', 'NOW', '["VITAMIN_C", "CALCIUM", "MAGNESIUM"]', 'RECOMMEND', FALSE, '["GUT", "GENERAL", "IMMUNITY"]', '[{"category": "DISEASE_CONSULT", "text": "나트륨 제제는 주의가 필요"}]', '속쓰림이 있는 사람에게 산성으로 인한 자극을 줄여 선택을 권장하며, 칼슘·마그네슘 염을 붙인 중성형을 추천한다고 설명.', X'', 'text-embedding-3-small', 221, NULL, 'review-extract-v3');
